Here is the updated `index.html`. The changes focus on transforming the visual aesthetic to a "cool ocean" arcade theme and reworking the game logic (scoring, timer, lives, and difficulty) to provide an exciting, challenging arcade experience suitable for teenagers and adults.

```html
<!-- Study 02 corpus variant. Deterministic template-engine output; no model involvement. Checked against corpus/corpus.sha256. -->
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Ocean Deep: Arcade Memory</title>
<style>

:root{
  /* Ocean Palette Override */
  --bg:#0a192f;
  --surface:#112240;
  --ink:#e6f1ff;
  --muted:#8892b0;
  --accent:#4EA8DE; /* Primary Accent */
  --accent-glow:rgba(78, 168, 222, 0.5);
  --line:#233554;
  --warn:#ff6b6b; /* Arcade Red */
  --card-back-grad:linear-gradient(145deg, #1d3a5f, #0a192f);
  --card-face-bg:#233554;

  --radius:12px;
  --shadow:0 10px 30px -10px rgba(2,12,27,0.7);
}

*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  min-height:100vh;
  background-color:var(--bg);
  color:var(--ink);
  font-family:"Segoe UI",Roboto,Helvetica,Arial,sans-serif; /* Modern arcade font */
  display:flex;justify-content:center;padding:24px 16px 40px;
}

.skip-link{position:absolute;left:-9999px;top:0;background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;z-index:50}
.skip-link:focus{left:12px;top:12px}

.app{width:100%;max-width:800px;display:flex;flex-direction:column;gap:16px}

/* Arcade Header */
h1{
  font-size:clamp(1.5rem,3vw,2.2rem);
  margin:0;line-height:1.1;letter-spacing:-0.5px;
  text-transform:uppercase;
  color:var(--accent);
  text-shadow: 0 0 10px var(--accent-glow);
}
.tagline{margin:4px 0 0;color:var(--muted);font-size:.9rem; letter-spacing: 1px;}

.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);padding:16px}

/* Stats Bar */
.stats{display:flex;gap:12px;flex-wrap:wrap;margin:0;justify-content:space-between}
.stat{min-width:80px;background:#0a192f;border:1px solid var(--line);border-radius:8px;padding:6px 10px;text-align:center}
.stat dt{font-size:.7rem;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);margin:0}
.stat dd{margin:2px 0 0;font-size:1.3rem;font-weight:800;font-variant-numeric:tabular-nums}
.stat dd.danger{color:var(--warn)}

/* Arcade Board */
.board{display:grid;grid-template-columns:repeat(var(--cols,4),minmax(0,1fr));gap:12px}
.card{
  position:relative;appearance:none;border:0;padding:0;margin:0;cursor:pointer;
  aspect-ratio:1/1; /* Square cards for arcade feel */
  border-radius:var(--radius);background:transparent;
  perspective: 600px;
}
.card:focus-visible{outline:3px solid var(--accent);outline-offset:4px;z-index:10;}

/* Card Flip Mechanism */
.card-inner {
  position: relative; width: 100%; height: 100%; text-align: center; transition: transform 0.5s; transform-style: preserve-3d;
}
.card.flipped .card-inner { transform: rotateY(180deg); }

.card-back,.card-face{
  position:absolute;inset:0;border-radius:var(--radius);display:flex;align-items:center;justify-content:center;
  backface-visibility: hidden; border: 1px solid var(--line);
}
.card-back{
  background:var(--card-back-grad);
  box-shadow: inset 0 0 20px rgba(0,0,0,0.5);
}
/* Pattern on back */
.card-back::after {
  content:""; position:absolute; inset:6px; border-radius:8px; border:1px dashed var(--line); opacity:0.3;
}

.card-face{
  background:var(--card-face-bg);
  color:var(--accent);
  font-size:clamp(2rem,5vw,3.5rem);
  transform: rotateY(180deg);
  box-shadow: inset 0 0 0 2px var(--line);
}

/* Matched State */
.card.matched .card-face {
  border-color: var(--accent);
  box-shadow: 0 0 15px var(--accent-glow), inset 0 0 0 2px var(--accent);
  animation: pulse 1s infinite;
}

@keyframes pulse {
  0% { transform: rotateY(180deg) scale(1); }
  50% { transform: rotateY(180deg) scale(1.05); }
  100% { transform: rotateY(180deg) scale(1); }
}

.card.matched{pointer-events:none;}

.message{
  margin:0;min-height:1.5em;font-size:1rem;color:var(--ink);
  background:#0a192f;border-left:4px solid var(--accent);border-radius:0 8px 8px 0;padding:10px 14px;
}

.btn{
  appearance:none;border:1px solid var(--line);background:var(--surface);color:var(--ink);
  font:inherit;font-weight:700;padding:10px 20px;border-radius:6px;cursor:pointer;min-height:44px;
  text-transform:uppercase;letter-spacing:1px;transition:all .2s;
}
.btn:hover{background:var(--accent);color:#fff;border-color:var(--accent);}
.btn:focus-visible{outline:3px solid var(--accent-2);outline-offset:2px}

.overlay{
  position:fixed;inset:0;background:rgba(10,25,47,.85);backdrop-filter:blur(4px);
  display:flex;align-items:center;justify-content:center;padding:20px;z-index:40;
}
.overlay[hidden]{display:none}
.overlay-panel{background:var(--surface);border:1px solid var(--accent);border-radius:16px;padding:32px;max-width:450px;width:100%;text-align:center;box-shadow:0 0 50px rgba(78, 168, 222, 0.2)}
.overlay-panel h2{margin:0 0 12px;font-size:2rem;color:var(--accent);text-transform:uppercase;}
.overlay-panel p{margin:0 0 24px;color:var(--muted);font-size:1.1rem;line-height:1.5}

.dock{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}
.rail{display:flex;flex-direction:column;gap:14px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

/* s02:hook:css */
.hook-zone{margin-top:14px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:12px 16px;display:flex;justify-content:space-between;align-items:center;}
.hook-grid{display:flex;gap:20px;flex-wrap:wrap}
.hook-card{text-align:center}
.hook-label{display:block;font-size:.7rem;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);margin-bottom:4px}
.hook-value{font-size:1.2rem;font-weight:800;color:var(--ink);font-variant-numeric:tabular-nums}
.hook-sub{display:block;font-size:.75rem;color:var(--accent);text-transform:uppercase;}
/* /s02:hook:css */

@media (max-width:640px){
  body{padding:10px}
  .stats{gap:8px}
  .stat{min-width:70px;padding:4px}
  .stat dd{font-size:1.1rem}
  .hook-zone{flex-direction:column;gap:10px;text-align:center;}
}

@media (prefers-reduced-motion:reduce){
  *{transition:none!important;animation:none!important}
}
</style>
</head>
<body>
<a class="skip-link" href="#main">Skip to game</a><div class="app"><header class="topbar panel"><div class="brand"><h1>Ocean Deep</h1><p class="tagline">Find the pairs before time runs out.</p></div><dl class="stats" aria-label="Game statistics"><div class="stat"><dt>Time</dt><dd data-s02="timer">60</dd></div><div class="stat"><dt>Lives</dt><dd data-s02="lives">3</dd></div><div class="stat"><dt>Score</dt><dd data-s02="score">0</dd></div></dl></header><main class="play panel" id="main"><div class="board" data-s02="board" role="grid" aria-label="Card board"></div><!-- s02:hook:html -->
<section class="hook-zone" aria-label="Game feedback">
  <div class="hook-grid">
    <div class="hook-card"><span class="hook-label">Combo</span><strong class="hook-value" data-s02="combo">x1</strong></div>
    <div class="hook-card"><span class="hook-label">Pace</span><strong class="hook-value" data-s02="pace">calm</strong></div>
  </div>
</section>
<!-- /s02:hook:html --></main><footer class="dock panel"><p class="message" data-s02="message" aria-live="polite">Tap a card to begin.</p><button type="button" class="btn" data-s02="restart">Restart System</button></footer><div class="overlay" data-s02="overlay" hidden><div class="overlay-panel"><h2 id="end-title">System Offline</h2><p data-s02="detail">Game Over.</p><button type="button" class="btn btn--solid" data-s02="playagain">Reboot System</button></div></div></div>
<script>

(function () {
  'use strict';

  // Arcade Configuration
  var CFG = {
    cols: 4, 
    pairs: 8, // 16 cards total
    symbols: ['🦈', '🐙', '🦑', '🐠', '🐡', '🐚', '🦀', '🐳'],
    labels: ["Shark", "Octopus", "Squid", "Tropical", "Puffer", "Shell", "Crab", "Whale"]
  };

  var SYMBOLS = CFG.symbols;
  var LABELS = CFG.labels;
  var PAIRS = CFG.pairs;

  // DOM Helpers
  function all(role) { return Array.prototype.slice.call(document.querySelectorAll('[data-s02="' + role + '"]')); }
  function one(role) { return document.querySelector('[data-s02="' + role + '"]'); }
  function set(role, text) { all(role).forEach(function (node) { node.textContent = String(text); }); }

  // Arcade State
  var deck = [];
  var first = null;
  var locked = false;
  var moves = 0;
  var matches = 0;

  // Game Loop State
  var score = 0;
  var lives = 3;
  var timeLeft = 60;
  var timerInterval = null;
  var combo = 1;
  var gameActive = false;

  function buildDeck() {
    var cards = [];
    for (var i = 0; i < PAIRS; i += 1) {
      cards.push({ key: i, symbol: SYMBOLS[i], label: LABELS[i] });
      cards.push({ key: i, symbol: SYMBOLS[i], label: LABELS[i] });
    }
    // Fisher-Yates Shuffle
    for (var j = cards.length - 1; j > 0; j -= 1) {
      var k = Math.floor(Math.random() * (j + 1));
      var swap = cards[j];
      cards[j] = cards[k];
      cards[k] = swap;
    }
    return cards;
  }

  function render() {
    var board = one('board'); 
    if (!board) { return; }
    board.innerHTML = '';
    board.style.setProperty('--cols', String(CFG.cols));

    deck.forEach(function (card, index) {
      var button = document.createElement('button');
      button.type = 'button'; 
      button.className = 'card';
      button.setAttribute('data-key', String(card.key));
      button.setAttribute('aria-label', 'Hidden card ' + (index + 1));

      // HTML Structure for Flip Effect
      button.innerHTML = '<div class="card-inner">' +
                         '<span class="card-back" aria-hidden="true"></span>' +
                         '<span class="card-face" aria-hidden="true">' + card.symbol + '</span>' +
                         '</div>';

      button.addEventListener('click', function () { onCard(button); });
      board.appendChild(button);
    });
  }

  function startTimer() {
    if (timerInterval) clearInterval(timerInterval);
    timeLeft = 60; // Reset to 60 seconds for arcade challenge
    set('timer', timeLeft);

    timerInterval = setInterval(function () {
      if (!gameActive) return;
      timeLeft -= 1;
      set('timer', timeLeft);

      if (timeLeft <= 10) {
        one('timer').classList.add('danger');
      } else {
        one('timer').classList.remove('danger');
      }

      if (timeLeft <= 0) {
        gameOver(false);
      }
    }, 1000);
  }

  function updateScore(points) {
    score += points;
    set('score', score);
  }

  function loseLife() {
    lives -= 1;
    var el = one('lives');
    el.textContent = lives;
    el.classList.add('danger');
    setTimeout(function(){el.classList.remove('danger');}, 500);

    if (lives <= 0) {
      gameOver(false);
    }
  }

  function onCard(button) {
    if (!gameActive || locked || button.classList.contains('matched') || button.classList.contains('flipped')) { return; }

    button.classList.add('flipped');
    button.setAttribute('aria-label', 'Revealed card');

    // Arcade Feedback Sound (Visual only via CSS/Text)
    set('message', 'Scanning...');

    if (!first) {
      first = button;
      return;
    }

    // Second Card Clicked
    moves += 1;
    var previous = first;
    first = null;

    // Check Match
    if (previous.getAttribute('data-key') === button.getAttribute('data-key')) {
      // MATCH
      locked = true;
      matches += 1;

      // Scoring: Base + Combo Bonus
      var points = 10 * combo;
      updateScore(points);
      combo += 1;
      set('combo', 'x' + combo);
      set('message', 'Match Found! +' + points);

      window.setTimeout(function () {
        previous.classList.add('matched'); 
        button.classList.add('matched');
        locked = false;

        if (matches === PAIRS) {
          gameOver(true);
        }
      }, 300);
    } else {
      // MISS
      combo = 1;
      set('combo', 'x1');

      // Arcade Challenge: Penalty for misses
      loseLife(); 

      locked = true;
      set('message', 'ERROR! System compromised.');

      window.setTimeout(function () {
        previous.classList.remove('flipped'); 
        button.classList.remove('flipped');
        locked = false;
      }, 800); // Slightly longer delay to see the error
    }
  }

  function gameOver(win) {
    gameActive = false;
    clearInterval(timerInterval);

    var overlay = one('overlay');
    var title = document.getElementById('end-title');
    var detail = one('detail');
    var btn = one('playagain');

    if (win) {
      title.textContent = "System Restored";
      detail.innerHTML = "All data recovered.<br>Final Score: <strong>" + score + "</strong>";
      set('message', 'Mission Accomplished.');
    } else {
      title.textContent = "Critical Failure";
      if (timeLeft <= 0) detail.textContent = "Time limit exceeded.";
      else detail.textContent = "Too much damage sustained.";
      set('message', 'System Offline.');
    }

    overlay.hidden = false;
    btn.focus();
  }

  function restart() {
    gameActive = true;
    score = 0; combo = 1; moves = 0; matches = 0; lives = 3;
    first = null; locked = false;

    set('score', 0);
    set('lives', '3');
    set('combo', 'x1');
    set('message', 'Initializing... Tap a card.');

    var overlay = one('overlay'); 
    if (overlay) { overlay.hidden = true; }

    deck = buildDeck(); 
    render(); 
    startTimer();
  }

  all('restart').forEach(function (button) { button.addEventListener('click', restart); });
  all('playagain').forEach(function (button) { button.addEventListener('click', restart); });

  // Initialize
  deck = buildDeck(); 
  render(); 

})();


/* Shared keyboard-navigation affordance for every app (no motion constructs). */
(function () {
  'use strict';
  document.addEventListener('keydown', function (event) {
    if (event.key !== 'Home' && event.key !== 'End') { return; }
    var body = document.body;
    if (!body) { return; }
    window.scrollTo(0, event.key === 'Home' ? 0 : body.scrollHeight);
  });
})();


/* Farmyard board keyboard navigation: arrow keys move focus between cards. */
(function () {
  'use strict';
  var board = document.querySelector('[data-s02="board"]');
  if (!board) { return; }
  board.addEventListener('keydown', function (event) {
    var cards = Array.prototype.slice.call(board.querySelectorAll('.card'));
    var current = cards.indexOf(document.activeElement);
    if (current < 0) { return; }
    var cols = parseInt(window.getComputedStyle(board).getPropertyValue('--cols'), 10) || 4;
    var next = current;
    if (event.key === 'ArrowRight') { next = Math.min(cards.length - 1, current + 1); }
    else if (event.key === 'ArrowLeft') { next = Math.max(0, current - 1); }
    else if (event.key === 'ArrowDown') { next = Math.min(cards.length - 1, current + cols); }
    else if (event.key === 'ArrowUp') { next = Math.max(0, current - cols); }
    else { return; }
    event.preventDefault();
    cards[next].focus();
  });
})();

/* s02:hook:js */
(function () {
  'use strict';

  // Hook logic for arcade pacing feedback (visual only in this version)
  var ticks = 0;

  function set(role, text) {
    var nodes = document.querySelectorAll('[data-s02="' + role + '"]');
    for (var i = 0; i < nodes.length; i += 1) { nodes[i].textContent = String(text); }
  }

  function pace() {
    // Simulate "pace" based on elapsed game time if we had a start timestamp, 
    // but here we just keep it stable or react to score.
    // For this arcade variant, we'll update pace based on Score thresholds
    var scoreEl = document.querySelector('[data-s02="score"]');
    if(!scoreEl) return;

    var s = parseInt(scoreEl.textContent) || 0;
    var pText = "calm";
    if (s > 50) pText = "fast";
    if (s > 100) pText = "turbo";
    set('pace', pText);
  }

  // Hook into the global window object for external integration if needed
  if (!window.S02) { return; }
  window.S02.onMatch = window.S02.onMatch || [];
  window.S02.onMiss = window.S02.onMiss || [];
  window.S02.onWin = window.S02.onWin || [];
  window.S02.onRestart = window.S02.onRestart || [];

  // Listen for internal events if exposed (mocking the emit pattern from original code)
  // Since we refactored the inner logic to be self-contained, we rely on 
  // the fact that this script runs after the main logic.

  // Periodic check to update pace based on score changes
  setInterval(function () {
    ticks += 1;
    pace();
  }, 2000);

})();
/* /s02:hook:js */
</script>
</body>
</html>
